m?setid=474fb321-575c-4b97-9dbe-080061652ee4","pmid":null,"evidence_kind":"label_context","study_context":"source_context_requires_review","clinical_interpretation_validated":false,"population_context":{"requested_population":"pregnancy","source_population":["pregnancy"],"source_basis":"Source MeSH/label section or original population field; missing stays unknown.","matches_requested_population_confirmed":false,"age_band_confirmed":false,"notice":"Search filters and broad population labels do not confirm applicability. Preserve actual age, prematurity, gestational stage and study population."}},{"text":"As with other AEDs, physiological changes during pregnancy may affect lamotrigine concentrations and/or therapeutic effect.","source":"DailyMed 8.1 Clinical Considerations","url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=474fb321-575c-4b97-9dbe-080061652ee4","pmid":null,"evidence_kind":"label_context","study_context":"source_context_requires_review","clinical_interpretation_validated":false,"population_context":{"requested_population":"pregnancy","source_population":["pregnancy"],"source_basis":"Source MeSH/label section or original population field; missing stays unknown.","matches_requested_population_confirmed":false,"age_band_confirmed":false,"notice":"Search filters and broad population labels do not confirm applicability. Preserve actual age, prematurity, gestational stage and study population."}},{"text":"There have been reports of decreased lamotrigine concentrations during pregnancy and restoration of pre-pregnancy concentrations after delivery.","source":"DailyMed 8.1 Clinical Considerations","url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=474fb321-575c-4b97-9dbe-080061652ee4","pmid":null,"evidence_kind":"label_context","study_context":"source_context_requires_review","clinical_interpretation_validated":false,"population_context":{"requested_population":"pregnancy","source_population":["pregnancy"],"source_basis":"Source MeSH/lab